"""Explicit per-frame PD teaching ribbons. Does not modify source MRI or labels.
No interpolation, automatic extrapolation, or diagnostic segmentation is used.
"""
import json,copy,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];A=R/'app/src/main/assets'
LIMIT='Все ленты и новые ориентиры приблизительные: показана ожидаемая топография, а не точные стенки, объём жидкости или доказанный бурсит. На срезах без разметки контуры не интерполируются. Нормальные спавшиеся сумки могут не различаться. Исходные точки проверены обзорно по топографии и терминологии; это не независимая врачебная верификация каждой точки.'
class Module:
 def __init__(self,m,code,group):
  self.m=m;self.code=code;self.group=group;self.d=json.loads((A/(m+'-data.json')).read_text());self.l=json.loads((A/(m+'-labels.json')).read_text());self.ss={s['sourceSeries']:s for s in self.d['series'] if s['id'].endswith('_dp')}
  self.e={'revision':'1.44','filters':[{'id':group,'name':'Сумки и завороты · ленты PD','default':True,'icon':'wrist-mri-source/group-1252.png'}], 'structureNotes':{},'catalogNames':{},'displayNames':{},'shortNames':{},'seriesSlices':{s['id']:{f['annotation']:{'points':[],'regions':[],'suppress':[]} for f in s['frames']} for s in self.ss.values()},'guideTitle':'Связки, сумки и завороты · подробнее','guideChapters':[],'sources':[],'limitations':[LIMIT]}
  self.structs={p['structure']:p['name'] for a in self.l['slices'].values() for p in a['points']};self.reg={}
 def define(self,id,name,short,note,kind='recess'):
  self.e['structureNotes'][str(id)]=note+' '+('Суставной заворот — продолжение полости соответствующего сустава, не самостоятельная сумка.' if kind=='recess' else 'Отдельная сумка; не отождествлять с полостью сустава.' if kind=='bursa' else '')+' Цветная лента — ориентировочная область, не сегментация.'
  self.e['catalogNames'][str(id)]=name;self.reg[id]=(name,short,kind)
 def ribbon(self,se,n,id,vs,width=5):
  name,short,kind=self.reg[id];s=self.ss[se];a=self.e['seriesSlices'][s['id']][s['frames'][n-1]['annotation']]
  a['regions'].append({'structure':id,'name':name,'shortName':short,'filter':self.group,'category':'organs','approximate':True,'kind':kind,'vertices':vs,'width':width})
 def rows(self,se,id,rows,width=5):
  for n,vs in rows.items():self.ribbon(se,n,id,vs,width)
 def notes(self,d):
  for id,note in d.items():self.e['structureNotes'][str(id)]=note
 def missing(self,id,name,note):self.e['catalogNames'][str(id)]=name;self.e['structureNotes'][str(id)]=note+' Отдельной уверенной покадровой метки в этом наборе нет; произвольная точка не добавлена.'
 def finish(self):
  for ss in self.e['seriesSlices'].values():
   for a in ss.values():a['regions'].sort(key=lambda r:r['structure'])
  (A/(self.m+'-anatomy144.json')).write_text(json.dumps(self.e,ensure_ascii=False,separators=(',',':'))+'\n')
  return {'module':self.m,'ribbons':sum(len(a['regions']) for ss in self.e['seriesSlices'].values() for a in ss.values()),'notes':len(self.e['structureNotes']),'sourceDataSha256':hashlib.sha256((A/(self.m+'-data.json')).read_bytes()).hexdigest(),'sourceLabelsSha256':hashlib.sha256((A/(self.m+'-labels.json')).read_bytes()).hexdigest(),'perSeries':{sid:{'framesWithRibbons':sum(bool(a['regions']) for a in ss.values()),'ribbons':sum(len(a['regions']) for a in ss.values())} for sid,ss in self.e['seriesSlices'].items()}}
